<script lang="ts">
  import savedSource from "./capture-source.json" with { type: "json" };
  import { onDestroy } from 'svelte';
  import { compileUiDocument, defaultSemanticElementCatalog, type UiDocument } from '@victframework/ui';
  import { ControlScope, DocumentHost, catalogDescriptors, catalogImplementations } from '@victframework/ui-svelte';
  import { captureRenderedElement } from '@victframework/ui-ai-svelte';
  import '@victframework/ui-svelte/styles.css';
  import '@victframework/ui-svelte/catalog.css';
  const source = savedSource as UiDocument;
  const compiled = compileUiDocument(source, defaultSemanticElementCatalog(), catalogDescriptors);
  let frame = $state<HTMLDivElement>();
  let captureUrl = $state(''), result = $state<unknown>(), measurements = $state<unknown>(), busy = $state(false), failure = $state('');
  let changes = $state<Record<string, unknown>>({});
  onDestroy(() => { if (captureUrl) URL.revokeObjectURL(captureUrl); });
  function measure() {
    const group = frame?.querySelector<HTMLElement>('[data-date-field-input]');
    const rect = (element: Element) => { const r = element.getBoundingClientRect(); return { x: r.x, y: r.y, width: r.width, height: r.height, top: r.top, right: r.right, bottom: r.bottom }; };
    return { frame: frame ? rect(frame) : null, group: group ? { ...rect(group), computedWidth: getComputedStyle(group).width, display: getComputedStyle(group).display, flexWrap: getComputedStyle(group).flexWrap, font: getComputedStyle(group).font } : null,
      segments: [...(frame?.querySelectorAll<HTMLElement>('[data-date-field-segment]') ?? [])].map(element => ({ text: element.textContent, part: element.getAttribute('data-segment'), ...rect(element), computedWidth: getComputedStyle(element).width, display: getComputedStyle(element).display, font: getComputedStyle(element).font })), runtimeState: changes };
  }
  async function capture() {
    if (!frame || busy) return;
    busy = true; failure = ''; measurements = measure();
    try {
      const image = await captureRenderedElement(frame);
      if (captureUrl) URL.revokeObjectURL(captureUrl);
      captureUrl = URL.createObjectURL(image.blob);
      const { blob, ...dimensions } = image;
      result = { ...dimensions, bytes: blob.size, mime: blob.type, capturedAt: new Date().toISOString(), before: measurements, after: measure() };
    } catch (error) { failure = error instanceof Error ? `${error.name}: ${error.message}${'captureReason' in error ? ` (${String(error.captureReason)})` : ''}` : String(error); }
    finally { busy = false; }
  }
</script>
<main><h1>Public capture fidelity probe</h1><p>Exact saved intake form source with canonical DateField, native name binding and shared card style. The image is generated by the installed public <code>captureRenderedElement</code>; no model, source substitute or fake image is involved.</p><div class="actions"><button onclick={capture} disabled={busy}>{busy ? 'Capturing…' : 'Capture actual canonical frame'}</button><button onclick={() => { measurements = measure(); }}>Measure actual date segments</button>{#if captureUrl}<a href={captureUrl} download="public-capture-fidelity.jpeg">Download actual capture</a><a href={`data:application/json;charset=utf-8,${encodeURIComponent(JSON.stringify(result, null, 2))}`} download="public-capture-geometry.json">Download capture geometry</a>{/if}</div><p role="status">{failure || (captureUrl ? 'Actual capture ready. Compare its date segments with the browser frame.' : 'Change the runtime input if desired, then capture.')}</p>
  <div class="comparison"><section><h2>Actual browser frame</h2><div class="frame" bind:this={frame}><ControlScope>{#if compiled.ok}<DocumentHost plan={compiled.plan} extensionDescriptors={catalogDescriptors} extensionImplementations={catalogImplementations} localState={source.localState} dispatch={async () => undefined} navigate={() => {}} onStateChange={(key, value) => { changes = { ...changes, [key]: value }; }} />{:else}<pre>{JSON.stringify(compiled, null, 2)}</pre>{/if}</ControlScope></div></section><section><h2>Actual public raster result</h2>{#if captureUrl}<img src={captureUrl} alt="Actual public capture of the canonical date field, runtime name and shared cards" />{:else}<p>No capture yet.</p>{/if}</section></div>
  <details open><summary>Actual geometry and capture metadata</summary><pre>{JSON.stringify(result ?? measurements, null, 2)}</pre></details>
</main>
<style>:global(body){margin:0;background:#f5f7fa;color:#172033;font:14px/1.5 system-ui}main{padding:20px;max-width:1420px;margin:auto}h1{font-size:25px}h2{font-size:17px}.actions{display:flex;gap:12px;align-items:center}button,a{font:inherit}button{padding:9px 12px;border:1px solid #9cb3d5;border-radius:6px;background:#fff;cursor:pointer}.comparison{display:grid;grid-template-columns:640px 640px;gap:24px}.frame{width:640px;border:1px solid #cbd5e1;background:white}img{max-width:100%;border:1px solid #cbd5e1}pre{font-size:11px;max-height:380px;overflow:auto;white-space:pre-wrap}details{margin-top:20px}@media(max-width:1350px){.comparison{grid-template-columns:640px}}</style>
